package com.jnapanam.sportszone.notification.controller;import com.jnapanam.sportszone.notification.dto.*;import com.jnapanam.sportszone.notification.service.NotificationService;import java.util.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/notifications")public class NotificationController{private final NotificationService service;public NotificationController(NotificationService s){service=s;}@GetMapping("/me")public List<NotificationResponse>mine(Authentication a){return service.mine(user(a));}@PatchMapping("/{id}/read")public NotificationResponse read(Authentication a,@PathVariable UUID id){return service.read(user(a),id);}@GetMapping("/preferences")public PreferenceResponse preference(Authentication a){return service.preference(user(a));}@PutMapping("/preferences")public PreferenceResponse preference(Authentication a,@RequestBody PreferenceRequest r){return service.preference(user(a),r);}private static UUID user(Authentication a){return UUID.fromString(a.getName());}}
